  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not segments:
        raise ValueError('No segments')
    required = ['name', 'importance', 'minimum', 'capacity']
    for seg in segments:
        for key in required:
            if key not in seg:
                raise ValueError(f'Missing key {key} in segment')
    names = [seg['name'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    minimums = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    total_min = sum(minimums)
    total_cap = sum(capacities)
    if budget < total_min:
        raise ValueError(f'Budget {budget} less than total minimum {total_min}')
    if budget > total_cap:
        raise ValueError(f'Budget {budget} exceeds total capacity {total_cap}')
    allocs = minimums[:]
    allocated = total_min
    while allocated < budget:
        best_idx = -1
        best_num = 0
        best_den = 1
        for i in range(len(segments)):
            if allocs[i] >= capacities[i]:
                continue
            next_pos = allocs[i] + 1
            num = importances[i]
            den = next_pos
            if best_idx == -1:
                best_idx = i
                best_num = num
                best_den = den
            else:
                left = num * best_den
                right = best_num * den
                if left > right or (left == right and i < best_idx):
                    best_idx = i
                    best_num = num
                    best_den = den
        if best_idx == -1:
            raise ValueError('Cannot allocate more')
        allocs[best_idx] += 1
        allocated += 1
    by_name = {names[i]: allocs[i] for i in range(len(segments))}
    return {
        'allocations': allocs,
        'by_name': by_name,
        'total': allocated
    }"
}
